import os,json,subprocess,re
from pathlib import Path
root=Path('/srv/projects')
names=['Codex','VPS','fadego','iptvpn-bot','lowcost-europa','pink-iptv','skill-universal','telegram-robot-leads']
def run(cmd, timeout=12):
 try:
  x=subprocess.run(cmd,capture_output=True,text=True,timeout=timeout,env={**os.environ,'GIT_OPTIONAL_LOCKS':'0','GIT_TERMINAL_PROMPT':'0'})
  return {'rc':x.returncode,'text':(x.stdout or '').strip()[:1500]}
 except Exception as e:return {'rc':-99,'error':type(e).__name__}
def git(d,*args):
 return run(['git','-C',str(d),*args])
def val(d,*args):
 x=git(d,*args);return x.get('text') if x.get('rc')==0 else None
out={'scope':'github-vps pre-sync read-only inventory','read_only':True,'projects':{},'services':{},'ferrari_alias':{},'disk_free_bytes':None}
for n in names:
 p=root/n
 info={'exists':p.exists(),'is_symlink':p.is_symlink(),'git':False}
 if not p.is_dir() or p.is_symlink():out['projects'][n]=info;continue
 info['physical_path']=str(p.resolve())
 info['git']=val(p,'rev-parse','--is-inside-work-tree')=='true'
 info['current_link']=(os.readlink(p/'current') if (p/'current').is_symlink() else None)
 info['entries']=[x.name for x in sorted(p.iterdir()) if x.name in ('.git','releases','current','.venv','node_modules','.runtime','archive','private','data','tools','package.json','pyproject.toml')]
 if info['git']:
  info['head']=val(p,'rev-parse','HEAD')
